import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Stage 7 — learned search policy: results and findings","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/retros/stage7-learned-policy-results.md","filePath":"vendored/graphopt/project/retros/stage7-learned-policy-results.md"}`),a={name:`graphopt/project/retros/stage7-learned-policy-results.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="stage-7-—-learned-search-policy-results-and-findings" tabindex="-1">Stage 7 — learned search policy: results and findings <a class="header-anchor" href="#stage-7-—-learned-search-policy-results-and-findings" aria-label="Permalink to “Stage 7 — learned search policy: results and findings”">​</a></h1><p>Plan 0016 stage 7 (ADR 0003). What was built, what was measured, and what the numbers honestly say.</p><h2 id="what-was-built" tabindex="-1">What was built <a class="header-anchor" href="#what-was-built" aria-label="Permalink to “What was built”">​</a></h2><ul><li><code>catopt_core.trajectories</code> — <code>RuleSample</code> + <code>rule_samples</code> + a <strong>structural</strong> <code>rule_vector</code> (root-op buckets, full pattern-tree hash buckets, arities, check/derive flags). Torch-free.</li><li><code>catopt_torch.learned_policy</code> — <code>RuleValueNet</code> (an MLP) + <code>LearnedPolicy</code> (a <code>Policy</code>) + <code>train_rule_value</code>.</li><li><code>lab/train/train_search_policy.py</code> — pretrain on synthetic matmul chains, post-train on small real torch models (exported to IR), then predict a rule for a held-out program and score it against the best and the mean.</li></ul><p>The policy only <em>orders</em> legal moves; the certificate still decides correctness (ADR 0003 invariant 5). Nothing here can make a program wrong — only choose a better one.</p><h2 id="measured-result" tabindex="-1">Measured result <a class="header-anchor" href="#measured-result" aria-label="Permalink to “Measured result”">​</a></h2><p>Trained on the GPU (RTX 2050, <code>torch 2.14.1+cu130</code>), 3000 epochs:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>device: cuda</span></span>
<span class="line"><span>pretrain samples: 3060</span></span>
<span class="line"><span>posttrain samples: 408 (+3060 replay)</span></span>
<span class="line"><span>held-out cost before: 150</span></span>
<span class="line"><span>policy picks: assoc_matmul  (delta +54)</span></span>
<span class="line"><span>best delta: +54; mean +1</span></span>
<span class="line"><span>picked rank: 1/51</span></span></code></pre></div><p>The held-out program is <code>a(3,5)·(b(5,2)·c(2,3))</code> — the expensive bracketing, with <strong>k=5 unseen in training</strong> (training used 2–4). The policy picks <code>assoc_matmul</code>, which is the best rule (rank 1 of 51), improving the extracted cost by 54 FLOPs — the associativity move the engine&#39;s cost model already rewards, chosen by a learned model.</p><h2 id="findings-each-cost-real-work" tabindex="-1">Findings (each cost real work) <a class="header-anchor" href="#findings-each-cost-real-work" aria-label="Permalink to “Findings (each cost real work)”">​</a></h2><ol><li><strong>The structural encoding collided.</strong> Root-op buckets alone gave 51 rules → 23 distinct vectors. Adding a full pattern-tree hash took it to 49/51. Without this the policy cannot tell two <code>matmul</code> laws apart.</li><li><strong>Raw-delta regression collapses to the mean.</strong> Most rules leave the cost unchanged, so MSE predicts ~0 everywhere. Training on <code>delta &gt; 0</code> with BCE fixed the ranking.</li><li><strong>Input standardisation is load-bearing.</strong> Raw features (FLOPs in the thousands) next to 0/1 one-hots starve the MLP; fitting mean/std buffers moved the held-out pick from rank 13 to rank 2.</li><li><strong>Post-training forgets.</strong> Fine-tuning on the small-model family alone drops the chain pick from rank 1 to rank 2 — catastrophic forgetting. Replaying the pretraining family during post-training restores rank 1. This is why the script trains on <code>pre + post</code>.</li><li><strong>It generalises across shapes.</strong> The held-out shape (k=5) was never seen; the policy still ranks the right rule first.</li></ol><h2 id="honest-limitations" tabindex="-1">Honest limitations <a class="header-anchor" href="#honest-limitations" aria-label="Permalink to “Honest limitations”">​</a></h2><ul><li><strong>One family.</strong> The demo trains on matmul chains. A mixed training set (chains + elementwise) dilutes the signal and the pick drops to rank 2 — the policy is not yet a general-purpose player.</li><li><strong>Deeper chains.</strong> On a 3-matmul chain the policy picks the right <em>family</em> (<code>assoc_matmul</code>) but the wrong direction (best was <code>assoc_matmul_rev</code>, +8) — rank 30/51. More structure in the rule encoding, or a value model over partial extractions, would help.</li><li><strong>Not full RL.</strong> This is supervised pretraining on one-step trajectories, not policy-gradient RL. The <code>Policy</code> port is the seam: a true RL policy is one more conforming value (the plan&#39;s stage 7 target), trained against the deterministic evaluator.</li><li><strong>Single-step credit.</strong> <code>rule_samples</code> scores each rule applied alone; it does not credit sequences of rules. Multi-step trajectories are the natural next dataset.</li></ul><h2 id="reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#reproduce" aria-label="Permalink to “Reproduce”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">.venv/bin/python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> lab/train/train_search_policy.py</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --device</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> cuda</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> \\</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">    --pretrain</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> 60</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --posttrain</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> 8</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --epochs</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> 3000</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --hidden</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> 96</span></span></code></pre></div>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};